package com.hoppinzq.agent;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.anthropic.models.messages.ContentBlockParam;
import com.anthropic.models.messages.TextBlockParam;
import com.hoppinzq.agent.base.ZQAgent;
import com.hoppinzq.agent.command.AgentCommandHandler;
import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.tool.ToolDefinition;
import com.hoppinzq.agent.tool.manager.TodoManager;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;
import java.util.Scanner;

import static com.hoppinzq.agent.constant.AIConstants.*;
import static com.hoppinzq.agent.tool.ToolDefinition.*;

/**
 * 子智能体实现
 *
 * 核心概念：
 * - 父智能体拥有 task 工具，可以派生子智能体
 * - 子智能体只拥有部分工具（read_file，write_file,edit_file），但没有 task 工具（防止递归）
 * - 子智能体从空的 messages[] 开始，执行自己的循环
 * - 子智能体只返回摘要文本给父智能体，不返回完整的上下文历史
 *
 * @author hoppinzq
 */
public class Agent04 extends ZQAgent {
    public static TodoManager todoManager;
    private int roundsSinceTodo = 0;
    private long lastTodoVersion = 0;

    public Agent04(AnthropicClient client, String model, List<ToolDefinition> tools, TodoManager todoManager) {
        super(client, model, tools);
        Agent04.todoManager = todoManager;
        this.lastTodoVersion = todoManager.getVersion();
    }

    @Override
    protected void onToolExecution(List<ContentBlockParam> toolResults) {
        long currentVersion = todoManager.getVersion();
        if (currentVersion > lastTodoVersion) {
            roundsSinceTodo = 0;
            lastTodoVersion = currentVersion;
        } else {
            roundsSinceTodo++;
        }

        if (roundsSinceTodo >= 3) {
            String reminder = String.format("""
                <reminder>
                您已经 %d 个回合没有更新待办事项列表了。请更新列表以反映当前进度。
                
                建议操作：
                1. 检查当前任务状态
                2. 更新已完成的任务
                3. 添加新的任务（如果需要）
                4. 调整任务优先级
                </reminder>
                """, roundsSinceTodo);
            toolResults.add(ContentBlockParam.ofText(TextBlockParam.builder()
                    .text(reminder)
                    .build()));
        }
    }

    public static void main(String[] args) {
        AnthropicClient client = AnthropicOkHttpClient.builder()
                .apiKey(API_KEY)
                .baseUrl(BASE_URL)
                .timeout(Duration.ofSeconds(TIMEOUT))
                .maxRetries(MAX_RETRIES)
                .build();
        todoManager = new TodoManager();

        List<ToolDefinition> tools = new ArrayList<>();
        tools.add(BashDefinition);
        tools.add(ReadFileDefinition);
        tools.add(EditFileDefinition);
        tools.add(WriteFileDefinition);
        tools.add(GlobDefinition);
        tools.add(ContentSearchDefinition);
        tools.add(TodoDefinition);
        tools.add(SubAgentDefinition);
        Agent04 mainAgent = new Agent04(client, MODEL, tools,todoManager);
        mainAgent.setSystemPrompt(buildSystemPrompt());
        mainAgent.setSessionManager(bootstrapSession(args));
        mainAgent.setCommandHandler(new AgentCommandHandler(null));
        mainAgent.run();
    }

    /**
     * 启动会话：若命令行传入了 sessionId 则尝试恢复；否则交互式询问。
     * <ul>
     *   <li>{@code java AgentXX <sessionId>} —— 直接恢复指定会话</li>
     *   <li>无参启动 —— 列出已有会话，输入序号恢复或回车开新会话</li>
     * </ul>
     */
    private static SessionManager bootstrapSession(String[] args) {
        SessionManager sm = new SessionManager();
        if (args.length > 0 && !args[0].isBlank()) {
            boolean ok = sm.resume(args[0]);
            System.out.println(ok
                    ? "已恢复会话 " + args[0]
                    : "会话 " + args[0] + " 不存在或为空，将以该 ID 开始新会话");
            return sm;
        }
        Scanner sc = new Scanner(System.in);
        List<String> sessions = sm.listSessions();
        if (sessions.isEmpty()) {
            sm.startNew();
            System.out.println("新会话已创建: " + sm.getSessionId());
            return sm;
        }
        System.out.println("\n\033[95m========== 历史会话 ==========\033[0m");
        for (int i = 0; i < sessions.size(); i++) {
            System.out.printf("\033[95m%d\033[0m) %s%n", i + 1, sessions.get(i));
        }
        System.out.print("输入序号恢复对应会话，或直接回车开启新会话: ");
        String line = sc.nextLine().trim();
        if (line.isEmpty()) {
            sm.startNew();
            System.out.println("新会话已创建: " + sm.getSessionId());
            return sm;
        }
        try {
            int idx = Integer.parseInt(line) - 1;
            if (idx >= 0 && idx < sessions.size()) {
                String id = sessions.get(idx);
                sm.resume(id);
                System.out.println("已恢复会话: " + id);
                return sm;
            }
        } catch (NumberFormatException ignore) {
            // 用户可能直接输入了 sessionId
            if (sessions.contains(line)) {
                sm.resume(line);
                System.out.println("已恢复会话: " + line);
                return sm;
            }
        }
        sm.startNew();
        System.out.println("输入无效，已开启新会话: " + sm.getSessionId());
        return sm;
    }

    /**
     * 构建系统提示词
     * @return 格式化的系统提示词
     */
    private static String buildSystemPrompt() {
        String osName = System.getProperty("os.name").toLowerCase();
        return String.format("""
            # 角色定义
            你是一个带有待办事项列表的主智能体。作为任务协调者和管理者，你可以将复杂的任务委托给子智能体来处理。
            
            # 工作环境
            你工作在 %s 操作系统，工作根目录为：%s
            
            # 可用工具说明
            
            ## 核心工具
            1. **bash** - 执行Shell命令
               - 支持cmd、powershell、bash三种类型
               - 如果不指定类型，系统会根据操作系统自动选择
               - 示例：打开网站使用 start [url]
            
            2. **文件操作工具**
               - read_file: 读取文件内容
               - write_file: 写入文件内容（文件不存在则创建）
               - edit_file: 编辑文件（替换指定文本）
               - glob: 列出目录内容（支持文件类型筛选）
            
            3. **搜索工具**
               - content_search: 使用ripgrep搜索代码或文本
               - 支持正则表达式、文件类型筛选、大小写控制
            
            4. **待办事项管理**
               - todo: 管理任务列表
               - 支持三种状态：pending（待处理）、in_progress（进行中）、completed（已完成）
               - 限制：最多20个任务，同时只能有一个进行中的任务
            
            5. **子智能体委托**
               - sub_agent: 将复杂任务委托给子智能体
               - 子智能体只有文件操作工具（read_file, write_file, edit_file）
               - 适合处理具体的文件操作任务
            
            # 工作流程指南
            
            ## 1. 任务接收与分析
            - 仔细理解用户需求
            - 分析任务复杂度
            
            ## 2. 待办事项管理
            - 使用todo工具创建或更新任务列表
            - 为每个任务分配唯一ID
            - 设置合理的任务状态
            
            ## 3. 任务执行策略
            - **简单任务**：直接使用相应工具完成
            - **复杂任务**：分解为子任务，使用sub_agent委托
            - **文件操作**：优先考虑使用子智能体处理
            
            ## 4. 进度跟踪
            - 定期更新待办事项状态
            - 任务完成后立即标记为completed
            - 开始新任务前更新状态为in_progress
            
            # 最佳实践
            
            ## 待办事项管理
            - 保持任务列表简洁明了
            - 使用描述性的任务内容
            - 及时更新任务状态
            - 注意：3个回合未更新待办事项会收到提醒
            
            ## 工具使用
            - edit_file工具要求oldStr必须完全匹配且唯一
            - write_file会自动创建不存在的文件
            - glob支持递归列出目录内容
            - content_search支持强大的正则表达式搜索
            
            ## 子智能体使用
            - 给子智能体清晰具体的任务描述
            - 子智能体适合处理文件读写、编辑等具体操作
            - 子智能体完成任务后会返回摘要结果
            
            # 约束条件
            
            1. **工作目录限制**：所有文件操作都在工作根目录下进行
            2. **待办事项限制**：最多20个任务，同时只能有一个进行中
            3. **提醒机制**：3个回合未更新待办事项会收到提醒
            4. **子智能体工具限制**：只有文件操作工具
            5. **文件编辑限制**：edit_file要求oldStr必须唯一匹配
            
            # 响应格式要求
            
            - 保持专业、清晰的沟通风格
            - 复杂任务提供执行计划
            - 任务完成后提供总结
            - 遇到问题时说明原因和解决方案
            
            请根据以上指南高效地完成任务，合理使用工具，保持良好的任务管理习惯。
            """, osName, ROOT);
    }
}

package com.hoppinzq.agent.base;

import com.anthropic.client.AnthropicClient;
import com.anthropic.core.JsonValue;
import com.anthropic.models.messages.*;
import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.hoppinzq.agent.command.AgentCommandHandler;
import com.hoppinzq.agent.session.SessionManager;
import com.hoppinzq.agent.tool.ToolDefinition;
import lombok.Data;

import java.util.*;

import static com.hoppinzq.agent.constant.AIConstants.*;

/**
 * 智能体基类
 * @author hoppinzq
 */
@Data
public class ZQAgent {
    private String systemPrompt;
    private final Scanner scanner;
    private final String model;
    protected final AnthropicClient client;
    private final List<ToolDefinition> tools;
    protected final List<MessageParam> messageParams = new ArrayList<>();
    private String taskResult;
    private boolean taskCompleted = false;
    private AgentCommandHandler commandHandler;

    /**
     * 会话管理器
     */
    protected SessionManager sessionManager;

    public ZQAgent(AnthropicClient client, String model, List<ToolDefinition> tools) {
        this.client = client;
        this.model = model;
        this.scanner = new Scanner(System.in);
        this.tools = tools;
    }

    public void setCommandHandler(AgentCommandHandler commandHandler) {
        this.commandHandler = commandHandler;
    }

    /**
     * 设置会话管理器，同时初始化命令处理器。
     */
    public void setSessionManager(SessionManager sessionManager) {
        this.sessionManager = sessionManager;
        this.commandHandler = sessionManager != null ? new AgentCommandHandler(sessionManager) : null;
    }

    public void run() {
        if (sessionManager != null) {
            int n = sessionManager.historySize();
            if (n > 0) {
                sessionManager.populate(messageParams);
                System.out.printf("\u001b[90m已恢复会话 %s，共 %d 条历史消息\u001b[0m%n",
                        sessionManager.getSessionId(), n);
            } else {
                System.out.printf("\u001b[90m新会话 %s\u001b[0m%n", sessionManager.getSessionId());
            }
        }
        System.out.println("开始对话吧（输入 /stats 查看统计，/usage 查看明细，/exit 退出）");
        while (true) {
            System.out.print("\u001b[94m你\u001b[0m: ");
            String userInput = scanner.nextLine();
            if (userInput.isEmpty()) {
                continue;
            }

            // 特殊命令：不发送给 LLM
            if (commandHandler != null && commandHandler.isCommand(userInput)) {
                commandHandler.handleCommand(userInput);
                continue;
            }

            MessageParam userMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(userInput)
                    .build();
            appendMessage(userMessage);

            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                System.out.println("错误: " + e.getMessage());
                e.printStackTrace();
                continue;
            }
            appendMessage(message.toParam());
            recordUsageIfNeeded(message);
            printText(message);

            while (isToolUse(message)) {
                MessageParam toolResultMessage = executeToolCalls(message);
                appendMessage(toolResultMessage);
                try {
                    message = chatMessage(messageParams);
                } catch (Exception e) {
                    System.out.println("错误: " + e.getMessage());
                    break;
                }
                appendMessage(message.toParam());
                recordUsageIfNeeded(message);
                printText(message);
            }
            warnIfTruncated(message);
        }
    }

    private void printText(Message message) {
        for (ContentBlock content : message.content()) {
            if (content.isText()) {
                String text = content.text().map(TextBlock::text).orElse("");
                if (!text.isBlank()) {
                    System.out.printf("\u001b[93mAI\u001b[0m: %s%n", text);
                }
            }
        }
    }

    private boolean isToolUse(Message message) {
        return message.stopReason()
                .map(StopReason.TOOL_USE::equals)
                .orElse(false);
    }

    private void warnIfTruncated(Message message) {
        boolean maxTokens = message.stopReason()
                .map(StopReason.MAX_TOKENS::equals)
                .orElse(false);
        if (maxTokens) {
            System.out.printf("\u001b[91m[警告]\u001b[0m 本轮回复被 max_tokens=%d 截断，工具调用可能不完整。建议调大 MAX_TOKENS。%n",
                    MAX_TOKENS);
        }
    }

    private MessageParam executeToolCalls(Message message) {
        List<ContentBlockParam> toolResults = new ArrayList<>();
        for (ContentBlock content : message.content()) {
            if (!content.isToolUse()) {
                continue;
            }
            ToolUseBlock toolUse = content.asToolUse();
            System.out.printf("\u001b[96m工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

            String toolResult = null;
            Exception toolError = null;
            ToolDefinition matched = null;
            for (ToolDefinition tool : tools) {
                if (tool.getName().equals(toolUse.name())) {
                    matched = tool;
                    break;
                }
            }
            if (matched == null) {
                toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                System.out.printf("\u001b[91m错误\u001b[0m: %s%n", toolError.getMessage());
            } else {
                try {
                    toolResult = invokeTool(matched, toolUse._input());
                    System.out.printf("\u001b[92m结果\u001b[0m: %s%n", toolResult);
                } catch (Exception e) {
                    toolError = e;
                    System.out.printf("\u001b[91m错误\u001b[0m: %s%n", e.getMessage());
                    e.printStackTrace();
                }
            }

            toolResults.add(ContentBlockParam.ofToolResult(
                    ToolResultBlockParam.builder()
                            .toolUseId(toolUse.id())
                            .content(toolError != null ? toolError.getMessage() : toolResult)
                            .isError(toolError != null)
                            .build()
            ));
        }
        return MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(MessageParam.Content.ofBlockParams(toolResults))
                .build();
    }

    /** 子类（如 Agent04）可重写此钩子，在工具执行后做额外处理（如待办提醒）。 */
    protected void onToolExecution(List<ContentBlockParam> toolResults) {
    }

    /**
     * 记录本次 LLM 调用的 token 使用情况（若设置了 SessionManager）。
     */
    private void recordUsageIfNeeded(Message message) {
        if (sessionManager != null && message.usage() != null) {
            sessionManager.recordUsage(message.usage());
        }
    }

    /**
     * 向 messageParams 追加一条消息；若设置了 {@link SessionManager}，
     * 同步持久化。所有需要记录历史的追加都应走此方法。
     */
    protected void appendMessage(MessageParam param) {
        messageParams.add(param);
        if (sessionManager != null) {
            sessionManager.onMessageAppended(param);
        }
    }

    private String invokeTool(ToolDefinition tool, JsonValue input) {
        if (tool.getType() == null) {
            if (input.asObject().isEmpty()) {
                throw new IllegalArgumentException("工具 '" + tool.getName() + "' 参数不是 JSON 对象");
            }
            ObjectNode root = OBJECT_MAPPER.createObjectNode();
            root.set("input", input.convert(JsonNode.class));
            root.put("tool_name", tool.getName());
            return tool.getFunction().apply(root.toString());
        } else {
            return tool.getFunction().apply(Objects.requireNonNull(input.convert(tool.getType())).toString());
        }
    }

    protected Message chatMessage(List<MessageParam> messageParams){
        // 准备工具配置
        List<ToolUnion> anthropicTools = new ArrayList<>();
        for (ToolDefinition tool : tools) {
            anthropicTools.add(ToolUnion.ofTool(
                    Tool.builder()
                            .name(tool.getName())
                            .description(tool.getDescription())
                            .inputSchema(tool.getInputSchema())
                            .build()
            ));
        }
        MessageCreateParams.Builder messageBuilder = MessageCreateParams.builder()
                .model(model)
                .messages(messageParams)
                .tools(anthropicTools);

        if(systemPrompt != null && !systemPrompt.isEmpty()){
            messageBuilder.system(systemPrompt);
        }

        messageBuilder.maxTokens(MAX_TOKENS);

        MessageCreateParams params = messageBuilder.build();
        return client.messages().create(params);
    }

    public String runTask(String prompt) {
        MessageParam userMessage = MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(prompt)
                .build();
        messageParams.add(userMessage);

        while (true) {
            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                return "Error: " + e.getMessage();
            }
            messageParams.add(message.toParam());

            for (ContentBlock content : message.content()) {
                if (content.isText()) {
                    Optional<TextBlock> text = content.text();
                    String result = text.map(TextBlock::text).orElse("");
                    if (!result.isBlank()) {
                        System.out.printf("\u001b[94m（子）AI\u001b[0m: %s%n", result);
                    }
                }
            }

            // 没有工具调用：把文本拼接后作为任务结果返回
            if (!isToolUse(message)) {
                warnIfTruncated(message);
                return message.content().stream()
                        .filter(ContentBlock::isText)
                        .map(cb -> cb.text().get().text())
                        .reduce("", (a, b) -> a + b);
            }

            // 处理本轮全部工具调用；其中 task_completed 直接短路返回
            List<ContentBlockParam> toolResults = new ArrayList<>();
            for (ContentBlock content : message.content()) {
                if (!content.isToolUse()) {
                    continue;
                }
                ToolUseBlock toolUse = content.asToolUse();
                System.out.printf("\u001b[96m（子）工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

                if ("task_completed".equals(toolUse.name())) {
                    try {
                        JsonValue input = toolUse._input();
                        Optional<Map<String, JsonValue>> object = input.asObject();
                        if (object.isPresent()) {
                            JsonValue res = object.get().get("result");
                            if (res != null && res.asString().isPresent()) {
                                return res.asString().get().toString();
                            }
                        }
                        return "Task completed.";
                    } catch (Exception e) {
                        return "Error parsing task_completed: " + e.getMessage();
                    }
                }

                String toolResult = null;
                Exception toolError = null;
                ToolDefinition matched = null;
                for (ToolDefinition tool : tools) {
                    if (tool.getName().equals(toolUse.name())) {
                        matched = tool;
                        break;
                    }
                }
                if (matched == null) {
                    toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                    System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", toolError.getMessage());
                } else {
                    try {
                        toolResult = invokeTool(matched, toolUse._input());
                        System.out.printf("\u001b[92m（子）结果\u001b[0m: %s%n", toolResult);
                    } catch (Exception e) {
                        toolError = e;
                        System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", e.getMessage());
                        e.printStackTrace();
                    }
                }

                toolResults.add(ContentBlockParam.ofToolResult(
                        ToolResultBlockParam.builder()
                                .toolUseId(toolUse.id())
                                .content(toolError != null ? toolError.getMessage() : toolResult)
                                .isError(toolError != null)
                                .build()
                ));
            }

            MessageParam toolResultMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(MessageParam.Content.ofBlockParams(toolResults))
                    .build();
            messageParams.add(toolResultMessage);
        }
    }

    /**
     * 执行任务并返回包含 token 使用情况的结果
     *
     * @param prompt 任务提示词
     * @return 包含结果和 token 使用情况的 SubAgentResult
     */
    public SubAgentResult runTaskWithTokenUsage(String prompt) {
        long totalInputTokens = 0;
        long totalOutputTokens = 0;

        MessageParam userMessage = MessageParam.builder()
                .role(MessageParam.Role.USER)
                .content(prompt)
                .build();
        messageParams.add(userMessage);

        while (true) {
            Message message;
            try {
                message = chatMessage(messageParams);
            } catch (Exception e) {
                return SubAgentResult.error("Error: " + e.getMessage());
            }
            messageParams.add(message.toParam());

            // 累积 token 使用情况
            if (message.usage() != null) {
                totalInputTokens += message.usage().inputTokens();
                totalOutputTokens += message.usage().outputTokens();
            }

            for (ContentBlock content : message.content()) {
                if (content.isText()) {
                    Optional<TextBlock> text = content.text();
                    String result = text.map(TextBlock::text).orElse("");
                    if (!result.isBlank()) {
                        System.out.printf("\u001b[94m（子）AI\u001b[0m: %s%n", result);
                    }
                }
            }

            // 没有工具调用：把文本拼接后作为任务结果返回
            if (!isToolUse(message)) {
                warnIfTruncated(message);
                String result = message.content().stream()
                        .filter(ContentBlock::isText)
                        .map(cb -> cb.text().get().text())
                        .reduce("", (a, b) -> a + b);
                return SubAgentResult.success(result, totalInputTokens, totalOutputTokens);
            }

            // 处理本轮全部工具调用；其中 task_completed 直接短路返回
            List<ContentBlockParam> toolResults = new ArrayList<>();
            for (ContentBlock content : message.content()) {
                if (!content.isToolUse()) {
                    continue;
                }
                ToolUseBlock toolUse = content.asToolUse();
                System.out.printf("\u001b[96m（子）工具\u001b[0m: %s(%s)%n", toolUse.name(), toolUse._input());

                if ("task_completed".equals(toolUse.name())) {
                    try {
                        JsonValue input = toolUse._input();
                        Optional<Map<String, JsonValue>> object = input.asObject();
                        if (object.isPresent()) {
                            JsonValue res = object.get().get("result");
                            if (res != null && res.asString().isPresent()) {
                                return SubAgentResult.success(
                                        res.asString().get().toString(),
                                        totalInputTokens,
                                        totalOutputTokens);
                            }
                        }
                        return SubAgentResult.success("Task completed.", totalInputTokens, totalOutputTokens);
                    } catch (Exception e) {
                        return SubAgentResult.error("Error parsing task_completed: " + e.getMessage());
                    }
                }

                String toolResult = null;
                Exception toolError = null;
                ToolDefinition matched = null;
                for (ToolDefinition tool : tools) {
                    if (tool.getName().equals(toolUse.name())) {
                        matched = tool;
                        break;
                    }
                }
                if (matched == null) {
                    toolError = new Exception("工具 '" + toolUse.name() + "' 没有找到");
                    System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", toolError.getMessage());
                } else {
                    try {
                        toolResult = invokeTool(matched, toolUse._input());
                        System.out.printf("\u001b[92m（子）结果\u001b[0m: %s%n", toolResult);
                    } catch (Exception e) {
                        toolError = e;
                        System.out.printf("\u001b[91m（子）错误\u001b[0m: %s%n", e.getMessage());
                        e.printStackTrace();
                    }
                }

                toolResults.add(ContentBlockParam.ofToolResult(
                        ToolResultBlockParam.builder()
                                .toolUseId(toolUse.id())
                                .content(toolError != null ? toolError.getMessage() : toolResult)
                                .isError(toolError != null)
                                .build()
                ));
            }

            MessageParam toolResultMessage = MessageParam.builder()
                    .role(MessageParam.Role.USER)
                    .content(MessageParam.Content.ofBlockParams(toolResults))
                    .build();
            messageParams.add(toolResultMessage);
        }
    }
}

package com.hoppinzq.agent.base;

import com.anthropic.client.AnthropicClient;
import com.anthropic.client.okhttp.AnthropicOkHttpClient;
import com.hoppinzq.agent.tool.ToolDefinition;
import com.hoppinzq.agent.tool.schema.SubAgentInput;
import lombok.extern.slf4j.Slf4j;

import java.time.Duration;
import java.util.ArrayList;
import java.util.List;

import static com.hoppinzq.agent.constant.AIConstants.*;
import static com.hoppinzq.agent.tool.ToolDefinition.*;

/**
 * 子Agent助手类
 * 用于创建和管理子智能体，处理具体的文件操作任务
 *
 * @author hoppinzq
 */
@Slf4j
public class SubAgent {

    /**
     * 执行子Agent任务（带 Token 统计）
     *
     * @param client Anthropic客户端实例，用于与AI模型交互
     * @param model 使用的AI模型名称
     * @param input 子Agent的输入参数，包含任务提示词等信息
     * @return 包含执行结果和 Token 使用情况的 SubAgentResult
     */
    public static SubAgentResult executeSubAgentWithTokenUsage(AnthropicClient client, String model, SubAgentInput input) {
        try {
            if (LOG_ENABLE) {
                log.info("--- 子Agent启动 ---");
                log.info("子Agent提示词: {}", input.getPrompt());
            }

            // 创建子Agent可用的工具列表
            List<ToolDefinition> subTools = new ArrayList<>();
            subTools.add(ReadFileDefinition);    // 添加读取文件工具
            subTools.add(EditFileDefinition);    // 添加编辑文件工具
            subTools.add(WriteFileDefinition);   // 添加写入文件工具

            // 创建子Agent实例，配置客户端、模型和可用工具
            ZQAgent subAgent = new ZQAgent(client, model, subTools);

            // 设置系统提示词，定义子Agent的角色和行为
            subAgent.setSystemPrompt("你是一个子智能体。你已接收一个具体任务，请使用可用的工具（读取文件、写入文件、编辑文件、搜索内容）来完成该任务。任务完成后，请直接返回结果。");

            // 执行任务并获取结果（包含 Token 统计）
            SubAgentResult result = subAgent.runTaskWithTokenUsage(input.getPrompt());

            if (LOG_ENABLE) {
                log.info("--- 子Agent结束 ---");
                log.info("子Agent执行结果: {}", result.getResult());
                log.info(result.formatTokenUsage());
            }

            return result;
        } catch (Exception e) {
            // 捕获异常并记录错误日志
            String errorMsg = "子Agent执行错误: " + e.getMessage();
            if (LOG_ENABLE) {
                log.error(errorMsg, e);
            }
            return SubAgentResult.error(errorMsg);
        }
    }

    /**
     * 执行子Agent任务
     *
     * @param client Anthropic客户端实例，用于与AI模型交互
     * @param model 使用的AI模型名称
     * @param input 子Agent的输入参数，包含任务提示词等信息
     * @return 子Agent执行结果，如果出错则返回错误信息
     */
    public static String executeSubAgent(AnthropicClient client, String model, SubAgentInput input) {
        SubAgentResult result = executeSubAgentWithTokenUsage(client, model, input);
        if (LOG_ENABLE) {
            log.info(result.formatTokenUsage());
        }
        return result.getResult();
    }

    /**
     * 执行子Agent任务（使用默认配置）
     *
     * @param input 子Agent的输入参数，包含任务提示词等信息
     * @return 子Agent执行结果，如果出错则返回错误信息
     */
    public static String executeSubAgent(SubAgentInput input) {
        // 使用默认配置创建Anthropic客户端
        AnthropicClient client = AnthropicOkHttpClient.builder()
                .apiKey(API_KEY)
                .baseUrl(BASE_URL)
                .timeout(Duration.ofSeconds(TIMEOUT))
                .maxRetries(MAX_RETRIES)
                .build();
        return executeSubAgent(client, MODEL, input);
    }

    /**
     * 执行子Agent任务（使用默认配置，带 Token 统计）
     *
     * @param input 子Agent的输入参数，包含任务提示词等信息
     * @return 包含执行结果和 Token 使用情况的 SubAgentResult
     */
    public static SubAgentResult executeSubAgentWithTokenUsage(SubAgentInput input) {
        // 使用默认配置创建Anthropic客户端
        AnthropicClient client = AnthropicOkHttpClient.builder()
                .apiKey(API_KEY)
                .baseUrl(BASE_URL)
                .timeout(Duration.ofSeconds(TIMEOUT))
                .maxRetries(MAX_RETRIES)
                .build();
        return executeSubAgentWithTokenUsage(client, MODEL, input);
    }
}

package com.hoppinzq.agent.tool;

